import { PurposeType, SnapTimeType } from '../constants'

export type PresetDetailType = {
    // MAIN properties
    enableChatting?: boolean
    city?: string
    timezone?: string
    name?: string
    source?: string
    age?: string
    modelInfo?: string
    platform?: string
    link?: string
    dayTimeSetting?: string
    nightTimeSetting?: string
    language?: string
    detectLang?: boolean
    chattingStyle?: string
    matchUsersLocation?: boolean
    // SNAP properties
    snaps?: LiveSnapType[]

    // opener properties
    opener?: PresetOpenerType


    // CTA properties
    cta?: PresetCtaType
    snapsAdd?: PresetSnapsAddType

    // Settings properties
    settings?: PresetSettingType

    followUps?: PresetFollowUpType
}

export type PresetFollowUpType = {
    xHourFollowUp?: {
        defaultSetting?: boolean
        hours?: number
        messages: { message: string; id: string }[]
    }
}

export type PresetSettingType = {
    delayChatting?: number
    autoRefresh?: number
    dontReply?: number
}

export enum OUTFIT_TYPE {
    OUTFIT_1 = 'Outfit 1',
    OUTFIT_2 = 'Outfit 2',
    OUTFIT_3 = 'Outfit 3'
}

export type LiveSnapType = {
    id?: string
    purpose: PurposeType
    lightning: SnapTimeType
    snapUrl?: string
    description?: string
    outfit?: OUTFIT_TYPE
}

export type PresetOpenerType = {
    bDefaultSettings?: boolean
    bUseAIOpener?: boolean
    message?: string
    snapPoolType?: string // reference: snapSourceOptions.value
    specificSnapIds: string[]
}

export type PresetCtaType = {
    finalStaticMessage?: PresetCtaStaticMessageType
    // Add CTA
    ctaSet?: CtaSetType
}

export type CtaSetType = {
    ctaInfo: PresetCtaInfoType[]
    activeCta: number
    sendRandomCta: boolean
}

export type PresetCtaStaticMessageType = {
    message: string
    bDefaultStaticMessage: boolean
    snapIds: string[]
}

export type PresetCtaMessageType = {
    message: string
    bDefaultCtaMessage: boolean
    snapIds: string[]
}

export type PresetCtaInfoType = {
    platform: string
    link: string
    id: string
}

export type PresetSnapsAddType = {
    enabledSnapAdd?: boolean
    addLimit?: number
    addAcceptedCycle?:
        | {
              ranged: true
              addAcceptedCycleMin: number
              addAcceptedCycleMax: number
              addAcceptedCycleRate?: never
          }
        | {
              ranged: false
              addAcceptedCycleMin?: never
              addAcceptedCycleMax?: never
              addAcceptedCycleRate: number
          }
    delayPerCycle?:
        | {
              ranged: true
              delayPerCycleMin: number
              delayPerCycleMax: number
              delayPerCycleRate?: never
          }
        | {
              ranged: false
              delayPerCycleMin?: never
              delayPerCycleMax?: never
              delayPerCycleRate: number
          }
    declineQuickAdds?: boolean
}

export type PresetItemTypeType = 'folder' | 'preset' | null

export type PresetType = {
    details: PresetDetailType
    id: number
    item_type: PresetItemTypeType
    model_id: string
    parent_id: null | number
    title: string
    userid: string
}

export type ImageType = { base64: string; file: File; id: string }
export type DraftSnapType = ImageType & {
    purpose: PurposeType
    lightning: SnapTimeType
    description?: string
    outfit?: OUTFIT_TYPE
}

export type LocallySetPresetValueType = {
    city?: string
    timezone?: string
    matchUsersLocation?: boolean
}
