import {
    API_ENDPOINT,
    KEY_NEW_MESSAGE_IN_CONVERSATION,
    ERROR_MSG,
    ServiceMessageName,
    MESSAGE_SENT_SUCCESSFULLY,
    USER_FRIENDS_GET_SUCCESSFULLY
} from '@/lib/constants'
import { LocalStorage } from '@/lib/chrome-storage'

type FetchApiMessage = {
    url: string
    params: any
}

console.log('Background Service Worker Loaded')

let firstGetFriendCallFormData = true
let firstGetFriendCallHeader = true

chrome.runtime.onInstalled.addListener(async () => {
    chrome.tabs.create({
        url: `https://web.snapchat.com/`
    })
    console.log('On install reset form data and auth headers')
})

chrome.webRequest.onBeforeRequest.addListener(
    function (details) {
        // console.log(`Loading: ${details.url}`)

        try {
            if (details.url.endsWith(`ami/friends`) && firstGetFriendCallFormData) {
                console.log(JSON.stringify(details))
                LocalStorage.setItem('FRIENDS_FORMDATA', details.requestBody.formData)
                firstGetFriendCallFormData = false
            }
            if (
                details.url.endsWith(`messagingcoreservice.MessagingCoreService/UpdateConversation`)
            ) {
                LocalStorage.setItem(KEY_NEW_MESSAGE_IN_CONVERSATION, true)
            }
        } catch (error) {
            console.log(error)
        }
    },
    { urls: ['<all_urls>'] },
    ['requestBody']
)

chrome.webRequest.onBeforeSendHeaders.addListener(
    function (details) {
        // console.log(`Loading: ${details.url}`)

        try {
            if (details.url.endsWith(`ami/friends`) && firstGetFriendCallHeader) {
                LocalStorage.setItem('FRIENDS_AUTH_HEADERS', details.requestHeaders)
                firstGetFriendCallHeader = false
            }
        } catch (error) {
            console.log(error)
        }
    },
    { urls: ['<all_urls>'] },
    ['requestHeaders']
)

chrome.webRequest.onCompleted.addListener(
    function (details) {
        try {
            if (
                details.url.endsWith(
                    `messagingcoreservice.MessagingCoreService/CreateContentMessage`
                ) &&
                details.statusCode === 200
            ) {
                LocalStorage.setItem(MESSAGE_SENT_SUCCESSFULLY, true)
            }
            if (details.url.endsWith(`ami/friends`) && details.statusCode === 200) {
                LocalStorage.setItem(USER_FRIENDS_GET_SUCCESSFULLY, true)
            }
        } catch (error) {
            console.log(error)
        }
    },
    { urls: ['<all_urls>'] },
    ['responseHeaders']
)

chrome.action.onClicked.addListener(() => {
    chrome.tabs.query({ active: true, currentWindow: true }, tabs => {
        const activeTab = tabs[0]
        chrome.tabs.sendMessage(activeTab.id!, { type: 'toggleAction' })
    })
})

let presetAbortController = new AbortController()

chrome.runtime.onMessage.addListener((data, sender, callback) => {
    const eventHandler = {
        [ServiceMessageName.FetchApi]: async () => {
            const config = data.params as FetchApiMessage

            if (
                config.url === `${API_ENDPOINT}/check-analytic` ||
                config.url.startsWith(`${API_ENDPOINT}/story/get/`)
            ) {
                if (presetAbortController) {
                    presetAbortController.abort()
                }

                presetAbortController = new AbortController()
                config.params.signal = presetAbortController.signal
            }

            try {
                const response = await fetch(config.url, { ...config?.params })
                const resData = await response.json()
                if (!response.ok) throw new Error(resData?.message)
                callback(resData)
            } catch (error) {
                callback({
                    status: false,
                    message: error?.message || ERROR_MSG.SOMETHING_WENT_WRONG
                })
            }
        },
        [ServiceMessageName.RunBot]: async () => {
            chrome.tabs.sendMessage(sender.tab.id, { action: ServiceMessageName.RunBot })
        },
        [ServiceMessageName.StopBot]: async () => {
            chrome.tabs.sendMessage(sender.tab.id, { action: ServiceMessageName.StopBot })
        },
        [ServiceMessageName.UpdateBotConfig]: async () => {
            chrome.tabs.sendMessage(sender.tab.id, { action: ServiceMessageName.UpdateBotConfig })
        },
        [ServiceMessageName.PauseChatting]: async () => {
            chrome.tabs.sendMessage(sender.tab.id, {
                action: ServiceMessageName.PauseChatting,
                data: data.data
            })
        },
        [ServiceMessageName.ForceOffBot]: async () => {
            chrome.tabs.sendMessage(sender.tab.id, {
                action: ServiceMessageName.ForceOffBot,
                data: data.data
            })
        },
        [ServiceMessageName.GetChatOverLayData]: async () => {
            chrome.tabs.sendMessage(sender.tab.id, {
                action: ServiceMessageName.GetChatOverLayData
            })
        },
        [ServiceMessageName.ChatOverLay]: async () => {
            chrome.tabs.sendMessage(sender.tab.id, {
                action: ServiceMessageName.ChatOverLay,
                data: data
            })
        }
    }
    if (eventHandler[data.action]) eventHandler[data.action]()

    return true
})

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
    const { status } = changeInfo

    const isSnapChatTab = tab?.url.startsWith('https://web.snapchat.com/')

    if (isSnapChatTab && status === 'loading') {
        LocalStorage.setItem(USER_FRIENDS_GET_SUCCESSFULLY, false)
        firstGetFriendCallFormData = true
        firstGetFriendCallHeader = true
    }

    if (changeInfo.status === 'unloaded' && isSnapChatTab) {
        console.log(`Tab ${tabId} is discarded. Reloading...`)
        // Reload the tab
        chrome.tabs.reload(tabId)
    }

    if (status == 'complete' && isSnapChatTab) {
        var debuggeeId = { tabId: tabId }
        var version = '1.3'

        chrome.debugger.attach(debuggeeId, version, function () {
            if (chrome.runtime.lastError) {
                console.log(chrome.runtime.lastError.message)
            } else {
                console.log('Successfully attached to the tab.')
                // You can now send commands to the tab.

                chrome.debugger.sendCommand(
                    debuggeeId,
                    'Emulation.setFocusEmulationEnabled',
                    { enabled: true },
                    () => {}
                )
            }
        })

    }
})

const activate = () => {
   console.log("!!!!!! run activate")
    if (activate.busy) {
        return
    }
    activate.busy = true

    chrome.storage.local.get(
        {
            hosts: ["web.snapchat.com"]
        },
        async prefs => {
            try {
                await chrome.scripting.unregisterContentScripts()

                if (prefs.hosts.length) {
                    const props = {
                        allFrames: true,
                        matchOriginAsFallback: true,
                        runAt: 'document_start'
                    } as chrome.scripting.RegisteredContentScript
                    if (prefs.hosts.includes('*')) {
                        props['matches'] = ['*://*/*']
                    } else {
                        props['matches'] = prefs.hosts.map(h => '*://' + h + '/*')
                    }

                    await chrome.scripting.registerContentScripts([
                        {
                            ...props,
                            id: 'main',
                            js: ['./main.js'],
                            world: 'MAIN'
                        },
                        {
                            ...props,
                            id: 'isolated',
                            js: ['./isolated.js'],
                            world: 'ISOLATED'
                        }
                    ])
                }
            } catch (e) {
                console.error('Blocker Registration Failed', e)
            }
            for (const c of activate.actions) {
                c()
            }
            activate.actions.length = 0
            activate.busy = false
        }
    )
}

chrome.runtime.onStartup.addListener(activate)
chrome.runtime.onInstalled.addListener(activate)
chrome.storage.onChanged.addListener(ps => {
    if (ps.enabled || ps.hosts) {
        activate()
    }
})
activate.busy = false
activate.actions = []

export {}
